+    curStruct.singleCoreDim = !curStruct.isDimTail ? maxDimPerCore : wholeDim - (realDim - 1) * maxDimPerCore;
     curStruct.dimIdxStart = dimIdx * maxDimPerCore;
     return true;
 }

